66	const DEFAULT_LIST_LIMIT = 20;
67	const STATUSES: readonly string[] = ["placed", "cancelled"];
68	
69	/** Query of `GET /orders?customerId=...[&status=placed|cancelled][&limit=1..100][&cursor=...]`. */
70	export function parseListOrdersQuery(params: URLSearchParams): CustomerOrdersQuery {
71	  const issues: ValidationIssue[] = [];
72	  const customerId = params.get("customerId") ?? "";
73	  if (customerId.trim() === "") {
74	    issues.push({ path: "customerId", message: "is required" });
75	  }
76	  const status = params.get("status");
77	  if (status !== null && !STATUSES.includes(status)) {
78	    issues.push({ path: "status", message: `must be one of ${STATUSES.join(", ")}` });
79	  }
80	  const rawLimit = params.get("limit");
81	  if (rawLimit !== null && !/^\d+$/.test(rawLimit)) {
82	    issues.push({ path: "limit", message: "must be a positive integer" });
83	  }
84	  if (issues.length > 0) {
85	    throw new ValidationError(issues);
86	  }
87	  const limit = rawLimit === null ? DEFAULT_LIST_LIMIT : Number(rawLimit);
88	  const cursor = params.get("cursor");
89	  return {
90	    customerId,
91	    limit,
92	    ...(status === null ? {} : { status: status as OrderStatus }),
93	    ...(cursor === null ? {} : { after: decodeCursor(cursor) }),
94	  };
95	}
